+using System.Security.Claims;
+using Microsoft.AspNetCore.Authorization;
+using Microsoft.AspNetCore.Mvc;
+using Microsoft.EntityFrameworkCore;
+
+[Authorize]
+[ApiController]
+[Route("api/orders")]
+public class OrdersController : ControllerBase
+{
+    private readonly ShopContext _db;
+
+    public OrdersController(ShopContext db) => _db = db;
+
+    [HttpGet("{id:int}")]
+    public async Task<ActionResult<OrderDto>> GetAsync(int id, CancellationToken cancellationToken)
+    {
+        var userId = User.FindFirstValue(ClaimTypes.NameIdentifier);
+
+        var order = await _db.Orders
+            .AsNoTracking()
+            .Where(o => o.Id == id && o.OwnerId == userId)
+            .Select(o => new OrderDto(o.Id, o.Total))
+            .FirstOrDefaultAsync(cancellationToken);
+
+        return order is null ? NotFound() : Ok(order);
+    }
+}
